  const n=value=>{if(!Number.isFinite(value))return '∞';let v=Math.max(0,value);if(v<1000)return (v<10&&v%1!==0?v.toFixed(1):Math.floor(v).toLocaleString('ja-JP'));let suffixes=['','k','M','B','T','Qa','Qi','Sx','Sp','Oc','No'];let idx=Math.floor(Math.log10(v)/3);if(idx>=suffixes.length)return v.toExponential(2);return +(v/Math.pow(1000,idx)).toFixed(2)+suffixes[idx]};
